mapper.select:
SELECT destination_id, dest_latitude, dest_longitude, dest_name, dest_address
FROM destinations
WHERE dest_name = #{destName}
  AND dest_address = #{destAddress}
LIMIT 1

SELECT destination_id, dest_latitude, dest_longitude, dest_name, dest_address
FROM destinations
WHERE dest_name = #{destName}
  AND dest_latitude BETWEEN #{minLatitude} AND #{maxLatitude}
  AND dest_longitude BETWEEN #{minLongitude} AND #{maxLongitude}
